/* Local document preparation: preserves the original; conservative crop, explicit review. */
let documentDraftPending=null;
function documentStorePending(mode,key,value){return new Promise((resolve,reject)=>{const open=indexedDB.open('rm-v11-1-document-draft',1);open.onupgradeneeded=()=>open.result.createObjectStore('originals');open.onerror=()=>reject(open.error);open.onsuccess=()=>{const db=open.result,tx=db.transaction('originals',mode),store=tx.objectStore('originals'),q=mode==='readwrite'?store.put(value,key):store.get(key);let result;q.onsuccess=()=>result=q.result;tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(tx.error);};};});}
const documentReadBasePending=identityRead10;
identityRead10=function(i){const d=i.documentImage;if(!d)return documentReadBasePending(i);return `<div class="identity-image-review"><img src="${d.processed}" alt="${T('Dokumen identitas yang disiapkan untuk pemeriksaan','Prepared identity document')}"><details data-original-document="${d.original.startsWith('idb:')?E(d.original.slice(4)):''}"><summary>${T('Lihat berkas asli','View original')}</summary><img ${d.original.startsWith('idb:')?'':`src="${d.original}"`} alt="${T('Berkas asli','Original file')}"></details><small>${T('Versi dokumen','Document version')} ${d.version}</small></div>`;};
document.addEventListener('toggle',async e=>{const d=e.target;if(!d.open||!d.dataset.originalDocument)return;try{if(typeof mayReadDocument120==='function'&&!mayReadDocument120(d))return;const src=await documentStorePending('readonly',d.dataset.originalDocument);if(typeof mayReadDocument120==='function'&&!mayReadDocument120(d))return;if(src)d.querySelector('img').src=src;else toast(T('Berkas asli tidak tersedia pada browser ini.','Original file is not available in this browser.'));}catch{toast(T('Berkas asli belum dapat dibuka.','Unable to open the original file.'));}},true);
function imagePending(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});}
async function prepareDocumentPending(src){
 const img=await imagePending(src),scale=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);
 const {width:w,height:h}=canvas,px=ctx.getImageData(0,0,w,h).data,corners=[0,(w-1)*4,(h-1)*w*4,(h*w-1)*4],bg=[0,1,2].map(k=>corners.reduce((n,j)=>n+px[j+k],0)/4),similar=corners.every(j=>bg.every((v,k)=>Math.abs(px[j+k]-v)<25));let minX=w,minY=h,maxX=0,maxY=0;
 if(similar)for(let y=0;y<h;y+=3)for(let x=0;x<w;x+=3){const i=(y*w+x)*4;if(bg.reduce((n,v,k)=>n+Math.abs(px[i+k]-v),0)>60){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}}
 const area=(maxX-minX)*(maxY-minY)/(w*h),safe=similar&&area>.25&&area<.94&&maxX-minX>w*.3&&maxY-minY>h*.3;
 const box=safe?{x:Math.max(0,minX-16),y:Math.max(0,minY-16),w:Math.min(w,maxX+16)-Math.max(0,minX-16),h:Math.min(h,maxY+16)-Math.max(0,minY-16)}:{x:0,y:0,w,h};
 documentDraftPending={original:src,source:canvas.toDataURL('image/jpeg',.92),width:w,height:h,box,rotation:box.h>box.w?90:0,detected:safe,base:RM10.pending.fingerprint(member10()),member:ten.member};await drawDocumentPending();return documentDraftPending;
}
async function drawDocumentPending(){const d=documentDraftPending;if(!d)return;const img=await imagePending(d.source),c=document.createElement('canvas'),b=d.box,side=d.rotation%180!==0;c.width=side?b.h:b.w;c.height=side?b.w:b.h;const ctx=c.getContext('2d');ctx.translate(c.width/2,c.height/2);ctx.rotate(d.rotation*Math.PI/180);ctx.drawImage(img,b.x,b.y,b.w,b.h,-b.w/2,-b.h/2,b.w,b.h);d.processed=c.toDataURL('image/jpeg',.92);document.querySelector('#prepared-document')?.setAttribute('src',d.processed);}
function documentControlsPending(){const d=documentDraftPending;return `<div class="document-workbench"><img id="prepared-document" src="${d.processed}" alt="${T('Pratinjau hasil penyesuaian','Prepared image preview')}"><p>${T('Periksa arah tulisan dan pastikan seluruh sisi kartu terbaca.','Check the text orientation and ensure every edge is readable.')}</p><div class="ten-actions">${pb(T('Putar 90°','Rotate 90°'),'document-rotate')}${pb(T('Gunakan seluruh gambar','Use full image'),'document-reset')}</div><details><summary>${T('Sesuaikan batas gambar','Adjust image edges')}</summary><div class="document-crop-fields">${[['x','Kiri','Left',d.width],['y','Atas','Top',d.height],['w','Lebar','Width',d.width],['h','Tinggi','Height',d.height]].map(([key,a,b,max])=>`<label>${T(a,b)}<input type="number" data-document-box="${key}" value="${Math.round(d.box[key])}" min="${key==='w'||key==='h'?1:0}" max="${max}"></label>`).join('')}</div></details><label class="document-confirm"><input type="checkbox" id="document-confirm">${T('Seluruh data dan sisi kartu terlihat jelas.','All details and card edges are clearly visible.')}</label>${pb(T('Simpan dokumen','Save document'),'document-save','','primary')}</div>`;}
document10=function(){if(!isLabel10())return;documentDraftPending=null;reviewDialogUI(T('Foto identitas','Identity image'),`<label class="document-upload">${T('Pilih foto identitas','Choose an identity image')}<input type="file" id="document-upload-pending" accept="image/jpeg,image/png,image/webp"></label>${pb(T('Gunakan gambar contoh','Use sample image'),'document-sample')}${info9('document-prepare',T('Draf lokal: gunakan dokumen contoh. Pemotongan latar dan orientasi sisi panjang disarankan otomatis, lalu diperiksa pengguna. Belum ada OCR, pemeriksaan keaslian, atau penyimpanan privat server.','Local draft: use a sample document. Background crop and landscape orientation are suggested automatically and reviewed by the user. OCR, authenticity checks, and private server storage are not connected.'))}<div id="document-workbench-slot"></div>`);};
async function sampleDocumentPending(){const c=document.createElement('canvas');c.width=920;c.height=720;const x=c.getContext('2d');x.fillStyle='#eee';x.fillRect(0,0,920,720);x.fillStyle='#a9d6e5';x.fillRect(95,145,730,440);x.fillStyle='#18394a';x.font='bold 30px sans-serif';x.fillText('DOKUMEN CONTOH — BUKAN KTP',125,210);x.font='24px sans-serif';x.fillText('NARA PRADANA',135,310);x.fillText('0000000000000000',135,350);x.fillText('Indonesia',135,390);x.fillStyle='#609cb0';x.fillRect(640,280,120,150);return c.toDataURL('image/png');}
async function mountDocumentPending(src){const slot=document.querySelector('#document-workbench-slot'),owner=ten.member;if(!slot)return;await prepareDocumentPending(src);if(slot.isConnected&&ten.member===owner)slot.innerHTML=documentControlsPending();}
window.addEventListener('change',async e=>{if(e.target.id==='document-upload-pending'){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){toast(T('Pilih JPG, PNG, atau WebP maksimal 5 MB.','Choose JPG, PNG, or WebP up to 5 MB.'));return;}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});await mountDocumentPending(src);}catch{toast(T('Gambar belum dapat dibuka. Coba berkas lain.','Unable to open this image. Try another file.'));}}
 if(e.target.dataset.documentBox){const d=documentDraftPending,k=e.target.dataset.documentBox;let n=+e.target.value;if(!Number.isFinite(n))return;d.box[k]=Math.max(k==='w'||k==='h'?1:0,n);d.box.x=Math.min(d.width-1,d.box.x);d.box.y=Math.min(d.height-1,d.box.y);d.box.w=Math.min(d.width-d.box.x,d.box.w);d.box.h=Math.min(d.height-d.box.y,d.box.h);await drawDocumentPending();document.querySelector('#document-confirm').checked=false;}});
window.addEventListener('click',async e=>{const b=e.target.closest('[data-pending^="document-"]');if(!b||b.dataset.pending==='document-review')return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.pending;
 if(a==='document-sample'){await mountDocumentPending(await sampleDocumentPending());return;}const d=documentDraftPending;if(!d)return;
 if(a==='document-rotate'){d.rotation=(d.rotation+90)%360;await drawDocumentPending();document.querySelector('#document-confirm').checked=false;}
 if(a==='document-reset'){d.box={x:0,y:0,w:d.width,h:d.height};await drawDocumentPending();document.querySelector('#document-workbench-slot').innerHTML=documentControlsPending();}
 if(a==='document-save'){try{if(!document.querySelector('#document-confirm').checked){toast(T('Periksa seluruh sisi kartu sebelum menyimpan.','Check all card edges before saving.'));return;}const m=member10();if(!isLabel10()||m.id!==d.member)throw Error('permission');if(RM10.pending.fingerprint(m)!==d.base)throw Error('stale');if(m.application?.status==='pending')throw Error('pending');const originalKey=browserId120();await documentStorePending('readwrite',originalKey,d.original);const image={original:'idb:'+originalKey,processed:d.processed,rotation:d.rotation,box:d.box,version:(m.identity.documentImage?.version||0)+1,at:ten.now};
  // The same versioned submission flow is required for identity replacement.
  if(m.active){if(m.documentRequest?.status==='pending')throw Error('pending');m.documentRequest={id:'doc-'+(++ten.serial),status:'pending',image,before:m.identity.documentImage||null,base:m.version,at:ten.now};}else RM10.act(ten,'profile',{identity:{document:true,documentImage:image}});
  save10();closeModal();render();toast(T(m.active?'Dokumen dikirim untuk diperiksa.':'Dokumen tersimpan.',m.active?'Document submitted for review.':'Document saved.'));}catch(err){toast(error10(err.message));}}
},true);
